documents.precision:
yamaa: '1.0'
type: spec
domain: TEST
keys: [ID]
input: {SRC: {path: input.csv, types: {VALUE: float}}}
output: {path: output.csv, columns: [ID, VALUE, DOUBLE], decimals: PRECISION}
columns:
  - {name: ID, type: int, derivation: SRC.ID}
  - {name: VALUE, type: float, derivation: SRC.VALUE}
  - {name: DOUBLE, type: float, derivation: 'VALUE + VALUE'}
